test.describe('FR-001, FR-003, FR-004, FR-005, FR-012, FR-013, US1-AS2, US1-AS4 … US1-AS8: add and view — run group serial:task-list', () => {
  // serial:task-list — every case adds tasks to the GLOBAL list and checks positions in it, so they must not run
  // beside each other (--workers 1); each case owns its tasks through its run prefix; mode 'default' keeps them independent
  test.describe.configure({ mode: 'default' });

  test('[TC-TODO-002] Adding "Buy milk" shows it at the top as not completed and clears the field', { tag: ['@positive', '@smoke', '@run:serial-task-list'] }, async ({ page, qaRun }, testInfo) => {
    const buyMilk = `${qaRun}-Buy milk`;
    const taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — no task titled "QA-<run>-Buy milk" is listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectNoTaskTitled(buyMilk);
    });
    await step('Type "QA-<run>-Buy milk" [D2] in "New task" — the field shows it', () => taskList.typeTitle(buyMilk));
    await step('Click "Add" — "QA-<run>-Buy milk" appears as the first task, without reloading', async () => {
      await taskList.clickAdd();
      await taskList.expectFirstTask(buyMilk);
    });
    await step('Check the task — it shows "Mark as completed" and not the text "Completed"', () => taskList.task(buyMilk).expectNotCompleted());
    await captureEvidence(taskList.page, testInfo);
    await step('Check the "New task" field — it is empty', () => taskList.expectFieldEmpty());
  });

  test('[TC-TODO-005] A title typed with spaces before and after is shown without them', { tag: ['@positive', '@run:serial-task-list'] }, async ({ page, qaRun }, testInfo) => {
    const padded = `${qaRun}-Padded title`;
    let taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — no task titled "QA-<run>-Padded title" is listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectNoTaskTitled(padded);
    });
    await step('Type "  QA-<run>-Padded title  " [D2] in "New task" — the field shows the title with the spaces', () => taskList.typeTitle(`  ${padded}  `));
    await step('Click "Add" — a task appears as the first task in the list', async () => {
      await taskList.clickAdd();
      await taskList.expectFirstTask(padded);
    });
    await step('Check the title of the first task — it reads exactly "QA-<run>-Padded title"', () => taskList.task(padded).expectTitleExactly(padded));
    taskList = await step('Close the browser window and open [E1] in a new browser window — "Loading tasks…" appears', () => taskList.reopenInNewWindow());
    await step('Wait until "Loading tasks…" clears — the task is listed', () => taskList.waitForListReady());
    await captureEvidence(taskList.page, testInfo);
    await step('Check the task — titled exactly "QA-<run>-Padded title", with no space before or after', () => taskList.task(padded).expectTitleExactly(padded));
  });

  test('[TC-TODO-006] Tasks added are shown with the same titles and states after reopening the application', { tag: ['@positive', '@run:serial-task-list'] }, async ({ page, qaRun }, testInfo) => {
    const buyMilk = `${qaRun}-Buy milk`;
    const callSam = `${qaRun}-Call Sam`;
    let taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — the task list (or "No tasks yet.") is shown', () => taskList.waitForListReady());
    await step('Type "QA-<run>-Buy milk" [D2] in "New task" — the field shows it', () => taskList.typeTitle(buyMilk));
    await step('Click "Add" — "QA-<run>-Buy milk" appears as the first task', async () => {
      await taskList.clickAdd();
      await taskList.expectFirstTask(buyMilk);
    });
    await step('Type "QA-<run>-Call Sam" [D2] in "New task" — the field shows it', () => taskList.typeTitle(callSam));
    await step('Click "Add" — "QA-<run>-Call Sam" appears as the first task, above "QA-<run>-Buy milk"', async () => {
      await taskList.clickAdd();
      await taskList.expectCaseOrder(qaRun, [callSam, buyMilk]);
    });
    taskList = await step('Close the browser window and open [E1] in a new browser window — "Loading tasks…" appears', () => taskList.reopenInNewWindow());
    await step('Wait until "Loading tasks…" clears — "QA-<run>-Call Sam" is listed above "QA-<run>-Buy milk"', async () => {
      await taskList.waitForListReady();
      await taskList.expectCaseOrder(qaRun, [callSam, buyMilk]);
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Check both tasks — each shows "Mark as completed" and not the text "Completed"', async () => {
      await taskList.task(callSam).expectNotCompleted();
      await taskList.task(buyMilk).expectNotCompleted();
    });
  });

  test('[TC-TODO-007] Every task shows its title and whether it is completed', { tag: ['@positive', '@run:serial-task-list'] }, async ({ page, context, qaRun }, testInfo) => {
    const buyMilk = `${qaRun}-Buy milk`;
    const callSam = `${qaRun}-Call Sam`;
    const payRent = `${qaRun}-Pay rent`;
    await step('Setup [D2]: add "QA-<run>-Buy milk", "QA-<run>-Call Sam", "QA-<run>-Pay rent" through "New task"', () => TaskListPage.addThroughPage(context, [buyMilk, callSam, payRent]));
    const taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — the three tasks are listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectCaseOrder(qaRun, [payRent, callSam, buyMilk]);
    });
    await step('Check the task "QA-<run>-Pay rent" — title as text, "Mark as completed", not "Completed"', async () => {
      await taskList.task(payRent).expectTitleExactly(payRent);
      await taskList.task(payRent).expectNotCompleted();
    });
    await step('Check the task "QA-<run>-Call Sam" — title as text, "Mark as completed", not "Completed"', async () => {
      await taskList.task(callSam).expectTitleExactly(callSam);
      await taskList.task(callSam).expectNotCompleted();
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Check the task "QA-<run>-Buy milk" — title as text, "Mark as completed", not "Completed"', async () => {
      await taskList.task(buyMilk).expectTitleExactly(buyMilk);
      await taskList.task(buyMilk).expectNotCompleted();
    });
  });

  test('[TC-TODO-008] Typing past 100 characters leaves exactly 100 in the field, and adding saves that title', { tag: ['@positive', '@run:serial-task-list'] }, async ({ page, qaRun }, testInfo) => {
    const hundred = dataItems.hundredCharacterTitle(qaRun);
    const taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — the task list (or "No tasks yet.") is shown', () => taskList.waitForListReady());
    await step('Type the 100-character title [D3] in "New task" — the field holds exactly that title', () => taskList.typeTitle(hundred));
    await step('Type "AAAAA" at the end of the field — the field still holds exactly the 100-character title', async () => {
      await taskList.typeAtEnd('AAAAA');
      await taskList.expectFieldValue(hundred);
    });
    await step('Click "Add" — a task appears as the first task in the list', async () => {
      await taskList.clickAdd();
      await taskList.expectFirstTask(hundred);
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Check the title of the first task — it is exactly the 100-character title [D3]', () => taskList.task(hundred).expectTitleExactly(hundred));
  });

  test('[TC-TODO-009] Pasting 120 characters leaves the first 100 in the field, and adding saves them', { tag: ['@positive', '@run:serial-task-list'] }, async ({ page, qaRun }, testInfo) => {
    const pasted = dataItems.hundredTwentyCharacterTitle(qaRun);
    const firstHundred = pasted.slice(0, 100);
    const taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — the task list (or "No tasks yet.") is shown', () => taskList.waitForListReady());
    await step('Paste the 120-character title [D3] into "New task" — the field holds its first 100 characters', async () => {
      await taskList.pasteTitle(pasted);
      await taskList.expectFieldValue(firstHundred);
    });
    await step('Click "Add" — a task appears as the first task in the list', async () => {
      await taskList.clickAdd();
      await taskList.expectFirstTask(firstHundred);
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Check the title of the first task — it is exactly the first 100 characters [D3]', () => taskList.task(firstHundred).expectTitleExactly(firstHundred));
  });

  test('[TC-TODO-010] Adding a title that already exists adds a second task with no warning', { tag: ['@positive', '@run:serial-task-list'] }, async ({ page, context, qaRun }, testInfo) => {
    const buyMilk = `${qaRun}-Buy milk`;
    await step('Setup [D2]: add "QA-<run>-Buy milk" through "New task"', () => TaskListPage.addThroughPage(context, [buyMilk]));
    const taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — exactly one task titled "QA-<run>-Buy milk" is listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectTaskTitledCount(buyMilk, 1);
    });
    await step('Type "QA-<run>-Buy milk" [D2] in "New task" — the field shows it', () => taskList.typeTitle(buyMilk));
    await step('Click "Add" — a second "QA-<run>-Buy milk" appears as the first task', async () => {
      await taskList.clickAdd();
      await taskList.expectFirstTask(buyMilk);
    });
    await step('Check the task list — exactly two separate tasks titled "QA-<run>-Buy milk"', () => taskList.expectTaskTitledCount(buyMilk, 2));
    await step('Check the page for a warning — no warning or error about a duplicate title', () => taskList.expectNoWarnings());
    await captureEvidence(taskList.page, testInfo);
    await step('Check both "QA-<run>-Buy milk" tasks — each has its own "Mark as completed" and "Delete"', async () => {
      await taskList.taskWithTitleAt(buyMilk, 0).expectOwnActions();
      await taskList.taskWithTitleAt(buyMilk, 1).expectOwnActions();
    });
  });

  test('[TC-TODO-011] A newly added task appears above the tasks added before it', { tag: ['@positive', '@run:serial-task-list'] }, async ({ page, context, qaRun }, testInfo) => {
    const buyMilk = `${qaRun}-Buy milk`;
    const callSam = `${qaRun}-Call Sam`;
    const payRent = `${qaRun}-Pay rent`;
    await step('Setup [D2]: add "QA-<run>-Buy milk" and then "QA-<run>-Call Sam" through "New task"', () => TaskListPage.addThroughPage(context, [buyMilk, callSam]));
    const taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — "QA-<run>-Call Sam" is listed above "QA-<run>-Buy milk"', async () => {
      await taskList.waitForListReady();
      await taskList.expectCaseOrder(qaRun, [callSam, buyMilk]);
    });
    await step('Type "QA-<run>-Pay rent" [D2] in "New task" — the field shows it', () => taskList.typeTitle(payRent));
    await step('Click "Add" — "QA-<run>-Pay rent" appears as the first task', async () => {
      await taskList.clickAdd();
      await taskList.expectFirstTask(payRent);
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Check the order of the case\'s tasks — "Pay rent", "Call Sam", "Buy milk"', () => taskList.expectCaseOrder(qaRun, [payRent, callSam, buyMilk]));
  });

  test('[TC-TODO-012] Double-clicking "Add" adds exactly one task', { tag: ['@positive', '@run:serial-task-list'] }, async ({ page, qaRun }, testInfo) => {
    const doubleAdd = `${qaRun}-Double add`;
    let taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — no task titled "QA-<run>-Double add" is listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectNoTaskTitled(doubleAdd);
    });
    await step('Type "QA-<run>-Double add" [D2] in "New task" — the field shows it', () => taskList.typeTitle(doubleAdd));
    await step('Double-click "Add" — "QA-<run>-Double add" appears as the first task', async () => {
      await taskList.doubleClickAdd();
      await taskList.expectFirstTask(doubleAdd);
    });
    await step('Check the task list — exactly one task titled "QA-<run>-Double add"', () => taskList.expectTaskTitledCount(doubleAdd, 1));
    taskList = await step('Close the browser window and open [E1] in a new browser window — "Loading tasks…" appears', () => taskList.reopenInNewWindow());
    await step('Wait until "Loading tasks…" clears — the list is shown', () => taskList.waitForListReady());
    await captureEvidence(taskList.page, testInfo);
    await step('Check the task list — exactly one task titled "QA-<run>-Double add" after reopening', () => taskList.expectTaskTitledCount(doubleAdd, 1));
  });
});
